document.addEventListener("DOMContentLoaded",function(){function t(){const t=parseFloat(e.value),n=parseFloat(a.value),i=parseFloat(o.value);if(isNaN(t)||isNaN(n)||isNaN(i)||t<=0||n<0||i<=0)return d.textContent="Please enter valid loan details.",l.innerHTML="",void 0;const s=n/12/100,r=12*i;let m;m=0===s?t/r:t*(s*Math.pow(1+s,r))/(Math.pow(1+s,r)-1);const c=m*r,u=c-t;d.innerHTML=`\n      <div class="result-item">\n        <strong>Monthly Payment:</strong> $${m.toFixed(2)}\n      </div>\n      <div class="result-item">\n        <strong>Total Amount:</strong> $${c.toFixed(2)}\n      </div>\n      <div class="result-item">\n        <strong>Total Interest:</strong> $${u.toFixed(2)}\n      </div>\n    `;let v='\n      <table class="payment-table">\n        <thead>\n          <tr>\n            <th>Payment #</th>\n            <th>Principal</th>\n            <th>Interest</th>\n            <th>Balance</th>\n          </tr>\n        </thead>\n        <tbody>\n    ',h=t;for(let t=1;t<=Math.min(12,r);t++){const n=h*s,e=m-n;h-=e,v+=`\n        <tr>\n          <td>${t}</td>\n          <td>$${e.toFixed(2)}</td>\n          <td>$${n.toFixed(2)}</td>\n          <td>$${h.toFixed(2)}</td>\n        </tr>\n      `}v+="</tbody></table>",r>12&&(v+="<p><em>Showing first 12 payments only</em></p>"),l.innerHTML=v}const n=document.getElementById("calculateBtn"),e=document.getElementById("loanAmount"),a=document.getElementById("interestRate"),o=document.getElementById("loanTerm"),d=document.getElementById("loanResult"),l=document.getElementById("paymentBreakdown");n&&n.addEventListener("click",t),[e,a,o].forEach(n=>{n&&n.addEventListener("input",function(){e.value&&a.value&&o.value&&t()})})});